function renderShape(c,l,w,h){c.beginPath();if(l.kind==='cross'){let a=w/6,b=h/6;c.moveTo(-a,-h/2);[ [a,-h/2],[a,-b],[w/2,-b],[w/2,b],[a,b],[a,h/2],[-a,h/2],[-a,b],[-w/2,b],[-w/2,-b],[-a,-b]].forEach(p=>c.lineTo(...p));c.closePath()}else if(l.kind==='crescent'){c.arc(0,0,w/2,Math.PI/2,Math.PI*1.5);c.bezierCurveTo(-w*.1,-h*.4,-w*.1,h*.4,0,h/2)}else if(l.kind==='quarter'){c.moveTo(-w/2,h/2);c.lineTo(-w/2,-h/2);c.ellipse(-w/2,h/2,w,h,-Math.PI/2,0,Math.PI/2);c.closePath()}else if(l.kind==='roundrect'){c.roundRect(-w/2,-h/2,w,h,[w*.15,w*.15,0,0])}else{let n=l.points||5,count=l.kind==='star'?n*2:n;for(let i=0;i<count;i++){let a=-Math.PI/2+i*Math.PI*2/count,r=l.kind==='star'&&i%2?(l.inner||.5):1;let x=Math.cos(a)*w/2*r,y=Math.sin(a)*h/2*r;i?c.lineTo(x,y):c.moveTo(x,y)}c.closePath()}c.fill()}
