async function loadCollageImages(files){
 if(collageLoading)return;
 const accepted=files.slice(0,20-media.length);if(!accepted.length)return toast('写真は20枚までです');
 const generation=++collageLoadGeneration;collageLoading=true;
 const results=new Array(accepted.length),existing=media.slice();let completed=0,failed=0;
 $('#collagePicker').hidden=true;closePanel();$('#empty').hidden=false;$('#empty').textContent='写真を読み込み中 0 / '+accepted.length;
 const began=performance.now();performance.mark('collage-import-start');
 const load=async(f,index)=>{
  let url;
  try{
   if(!f.type.startsWith('image/'))throw Error('画像を選んでください');
   url=URL.createObjectURL(f);const el=new Image();el.decoding='async';
   await new Promise((resolve,reject)=>{el.onload=resolve;el.onerror=()=>reject(Error('画像を読み込めません'));el.src=url});
   if(generation!==collageLoadGeneration){URL.revokeObjectURL(url);return}
   const item={el,url,type:'image',name:f.name,rotation:0,zoom:1,offsetX:0,offsetY:0};
   results[index]=item;media=existing.concat(results.filter(Boolean));
   $('#empty').hidden=true;draw();
   // Let the first rendered image reach the screen before preparing a reusable smaller buffer.
   requestAnimationFrame(()=>setTimeout(()=>{
    if(generation!==collageLoadGeneration||!media.includes(item))return;
    try{const preview=document.createElement('canvas'),scale=Math.min(1,1440/Math.max(el.naturalWidth,el.naturalHeight));preview.width=Math.max(1,Math.round(el.naturalWidth*scale));preview.height=Math.max(1,Math.round(el.naturalHeight*scale));preview.getContext('2d').drawImage(el,0,0,preview.width,preview.height);item.preview=preview}catch{}
   },0));
  }catch(e){if(url)URL.revokeObjectURL(url);failed++}
  finally{if(generation===collageLoadGeneration){completed++;$('#empty').textContent='写真を読み込み中 '+completed+' / '+accepted.length}}
 };
 // Two concurrent decodes keep two-photo imports fast without decoding 20 full-size photos at once.
 for(let i=0;i<accepted.length;i+=2){await Promise.all(accepted.slice(i,i+2).map((f,j)=>load(f,i+j)));if(generation!==collageLoadGeneration)return;if(i+2<accepted.length)await new Promise(resolve=>setTimeout(resolve,0))}
 collageLoading=false;$('#empty').hidden=media.length>0;$('#empty').textContent='＋から素材を選んでください';
 if(media.length){collageSelection=new Set(media.map((_,i)=>i));$('#collagePicker').hidden=true;history=[];future=[];pendingHistory=null;closePanel();resize()}
 performance.mark('collage-import-ready');performance.measure('collage-import','collage-import-start','collage-import-ready');
 $('#collagePicker').dataset.importMs=Math.round(performance.now()-began);
 if(failed)toast(failed+'枚の写真を読み込めませんでした');
}

function collageCellAt(p){
 const n=media.length;if(!n||p.x<0||p.x>1||p.y<0||p.y>1)return null;
 const cols=layout==='vertical'?1:layout==='horizontal'?n:Math.ceil(Math.sqrt(n)),rows=Math.ceil(n/cols);
 const col=Math.min(cols-1,Math.floor(p.x*cols)),row=Math.min(rows-1,Math.floor(p.y*rows)),index=row*cols+col;
 if(index>=n)return null;
 const x=col/cols+gap/canvas.width,y=row/rows+gap/canvas.height,w=1/cols-2*gap/canvas.width,h=1/rows-2*gap/canvas.height;
 return w>0&&h>0&&p.x>=x&&p.x<=x+w&&p.y>=y&&p.y<=y+h?{index,w,h}:null;
}
